def valid_date(date):
    import re

    # Rule 1: The date string is not empty.
    if not date:
        return False

    # Rule 4: The date should be in the format: mm-dd-yyyy
    date_format = re.compile(r'^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])-(\d{4})$')
    if not date_format.match(date):
        return False

    # Extract month, day, and year from the date string
    month, day, year = map(int, date.split('-'))

    # Rule 2: The number of days is validated by month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if not (1 <= day <= 31):
            return False
    elif month in [4, 6, 9, 11]:
        if not (1 <= day <= 30):
            return False
    elif month == 2:
        if not (1 <= day <= 29):
            return False
    else:
        return False

    # Rule 3: The months should not be less than 1 or higher than 12.
    if not (1 <= month <= 12):
        return False

    return True
